const results = $json.organic || [];

return [
  {
    json: {
      results: results.slice(0, 8).map((r, i) => ({
        rank: i + 1,
        title: r.title,
        link: r.link,
        snippet: r.snippet
      }))
    }
  }
];

let text = $json.output || $json.text || '';

text = text.replace(/\\n/g, '\n');

text = text.replace(
  /\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g,
  '$2'
);

text = text.replace(/\\\*/g, '*');

return [
  {
    json: {
      topic: $('On form submission').item.json.topic,
      report: text.trim(),
      generatedAt: new Date().toISOString()
    }
  }
];
